import { useState } from "react";
import { LifeBuoy, MessageCircle, Mail, CircleHelp as HelpCircle, ChevronDown } from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

const faqs = [
  { q: "How do I verify my student status?", a: "Go to Profile → Student Verification, enter your university and student number. Verification usually takes 1–2 business days." },
  { q: "How does the wallet work?", a: "Top up your wallet using any amount. Your balance is deducted when you place orders. You earn reward points on every purchase." },
  { q: "Can I get a refund?", a: "Yes. If your order is cancelled or there's an issue, the amount is refunded to your wallet within 24 hours." },
  { q: "How do reward points work?", a: "You earn 1 point per R1 spent. Points unlock tiers (Bronze → Silver → Gold → Diamond) and can be redeemed for free food and wallet credit." },
  { q: "Is my payment information secure?", a: "PayPlate uses bank-grade encryption. We never store your card details — payments are processed through secure payment gateways." },
];

export function SupportPage() {
  const [openFaq, setOpenFaq] = useState<number | null>(0);
  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");

  return (
    <AppShell>
      <div className="mx-auto max-w-2xl space-y-6">
        <div>
          <h1 className="font-heading text-2xl font-black lg:text-3xl">Help & Support</h1>
          <p className="mt-1 text-sm text-muted-foreground">We're here to help you</p>
        </div>

        {/* Contact options */}
        <div className="grid gap-3 sm:grid-cols-2">
          <Card className="flex items-center gap-3">
            <div className="grid size-12 place-items-center rounded-xl bg-primary/10 text-primary">
              <MessageCircle size={24} />
            </div>
            <div>
              <h3 className="font-bold">Live chat</h3>
              <p className="text-sm text-muted-foreground">Mon–Fri, 8am–8pm</p>
            </div>
          </Card>
          <Card className="flex items-center gap-3">
            <div className="grid size-12 place-items-center rounded-xl bg-primary/10 text-primary">
              <Mail size={24} />
            </div>
            <div>
              <h3 className="font-bold">Email us</h3>
              <p className="text-sm text-muted-foreground">support@payplate.app</p>
            </div>
          </Card>
        </div>

        {/* FAQs */}
        <div>
          <div className="mb-3 flex items-center gap-2">
            <HelpCircle size={18} className="text-primary" />
            <h2 className="font-heading text-lg font-black">Frequently asked questions</h2>
          </div>
          <div className="space-y-2">
            {faqs.map((faq, i) => (
              <Card key={i} className="p-0">
                <button
                  onClick={() => setOpenFaq(openFaq === i ? null : i)}
                  className="flex w-full items-center justify-between gap-3 p-4 text-left"
                >
                  <span className="font-bold">{faq.q}</span>
                  <ChevronDown
                    size={18}
                    className={cn("shrink-0 text-muted-foreground transition-transform", openFaq === i && "rotate-180")}
                  />
                </button>
                {openFaq === i && (
                  <div className="px-4 pb-4 text-sm text-muted-foreground">{faq.a}</div>
                )}
              </Card>
            ))}
          </div>
        </div>

        {/* Contact form */}
        <Card>
          <div className="mb-4 flex items-center gap-2">
            <LifeBuoy size={18} className="text-primary" />
            <h3 className="font-heading font-black">Send us a message</h3>
          </div>
          <div className="space-y-3">
            <Input label="Subject" placeholder="What do you need help with?" value={subject} onChange={(e) => setSubject(e.target.value)} />
            <div className="space-y-1.5">
              <label className="block text-sm font-bold">Message</label>
              <textarea
                className="h-32 w-full rounded-2xl border border-border bg-card px-4 py-3 text-sm font-medium outline-none transition-all focus:border-primary focus:ring-2 focus:ring-primary/20"
                placeholder="Describe your issue…"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
              />
            </div>
            <Button
              className="w-full"
              disabled={!subject.trim() || !message.trim()}
              onClick={() => { setSubject(""); setMessage(""); }}
            >
              Send message
            </Button>
          </div>
        </Card>
      </div>
    </AppShell>
  );
}

import { useState } from "react";
import { useNavigate } from "@/lib/router-compat";
import { motion } from "framer-motion";
import { Truck, Store, Wallet, CreditCard, CircleCheck as CheckCircle2, ArrowLeft, ArrowRight } from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { useCart } from "@/contexts/cart-context";
import { useOrders } from "@/contexts/orders-context";
import { useWallet } from "@/contexts/wallet-context";
import { useToast } from "@/contexts/toast-context";
import { useAuth } from "@/contexts/auth-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { formatRand } from "@/services/payplate-data";
import { cn } from "@/lib/utils";
import type { OrderType, PaymentMethod } from "@/types/payplate";

export function CheckoutPage() {
  const navigate = useNavigate();
  const { items, subtotalCents, studentDiscountCents, deliveryFeeCents, totalCents, clear } = useCart();
  const { createOrder } = useOrders();
  const { balanceCents } = useWallet();
  const { showToast } = useToast();
  const { user } = useAuth();
  const reduced = usePrefersReducedMotion();

  const [orderType, setOrderType] = useState<OrderType>("delivery");
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>("wallet");
  const [isProcessing, setIsProcessing] = useState(false);

  if (items.length === 0) {
    return (<AppShell><EmptyState icon={<span className="text-3xl">🛒</span>} title="Nothing to check out" description="Your cart is empty. Add some meals first!" action={<Button onClick={() => navigate("/restaurants")}>Browse restaurants</Button>} /></AppShell>);
  }

  const insufficientFunds = paymentMethod === "wallet" && balanceCents < totalCents;

  async function handleCheckout() {
    if (insufficientFunds) { showToast("Insufficient wallet balance. Top up or choose card.", "error"); return; }
    setIsProcessing(true);
    const restaurantId = items[0]?.item.restaurantId ?? "unknown";
    const restaurantName = items[0]?.item.restaurantId ? items[0].item.restaurantId.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()) : "Restaurant";
    setTimeout(() => {
      const order = createOrder({ items, subtotalCents, studentDiscountCents, promoDiscountCents: 0, deliveryFeeCents: orderType === "delivery" ? deliveryFeeCents : 0, totalCents: orderType === "delivery" ? totalCents : totalCents - deliveryFeeCents, orderType, paymentMethod, restaurantId, restaurantName });
      clear(); setIsProcessing(false); showToast("Order placed successfully!", "success"); navigate(`/payment-success/${order.id}`);
    }, 1500);
  }

  return (
    <AppShell>
      <div className="space-y-6">
        <div className="flex items-center gap-3"><button onClick={() => navigate("/cart")} className="grid size-10 place-items-center rounded-xl bg-card ring-1 ring-border"><ArrowLeft size={18} /></button><div><h1 className="font-heading text-2xl font-black lg:text-3xl">Checkout</h1><p className="text-sm text-muted-foreground">Review and place your order</p></div></div>
        <div className="grid gap-6 lg:grid-cols-3">
          <div className="space-y-4 lg:col-span-2">
            {/* Order type */}
            <Card><h3 className="font-heading font-black">Delivery or pickup?</h3><div className="mt-4 grid grid-cols-2 gap-3"><button onClick={() => setOrderType("delivery")} className={cn("flex items-center gap-3 rounded-2xl border-2 p-4 transition-all", orderType === "delivery" ? "border-primary bg-primary/5" : "border-border")}><div className={cn("grid size-10 place-items-center rounded-xl", orderType === "delivery" ? "bg-primary text-white" : "bg-muted")}><Truck size={20} /></div><div className="text-left"><p className="font-bold">Delivery</p><p className="text-xs text-muted-foreground">{formatRand(deliveryFeeCents)} fee</p></div></button><button onClick={() => setOrderType("pickup")} className={cn("flex items-center gap-3 rounded-2xl border-2 p-4 transition-all", orderType === "pickup" ? "border-primary bg-primary/5" : "border-border")}><div className={cn("grid size-10 place-items-center rounded-xl", orderType === "pickup" ? "bg-primary text-white" : "bg-muted")}><Store size={20} /></div><div className="text-left"><p className="font-bold">Pickup</p><p className="text-xs text-muted-foreground">No fee</p></div></button></div></Card>
            {/* Payment method */}
            <Card><h3 className="font-heading font-black">Payment method</h3><div className="mt-4 space-y-3"><button onClick={() => setPaymentMethod("wallet")} className={cn("flex w-full items-center justify-between rounded-2xl border-2 p-4 transition-all", paymentMethod === "wallet" ? "border-primary bg-primary/5" : "border-border")}><div className="flex items-center gap-3"><div className={cn("grid size-10 place-items-center rounded-xl", paymentMethod === "wallet" ? "bg-primary text-white" : "bg-muted")}><Wallet size={20} /></div><div className="text-left"><p className="font-bold">PayPlate Wallet</p><p className="text-xs text-muted-foreground">Balance: {formatRand(balanceCents)}</p></div></div>{paymentMethod === "wallet" && <CheckCircle2 size={20} className="text-primary" />}</button><button onClick={() => setPaymentMethod("card")} className={cn("flex w-full items-center justify-between rounded-2xl border-2 p-4 transition-all", paymentMethod === "card" ? "border-primary bg-primary/5" : "border-border")}><div className="flex items-center gap-3"><div className={cn("grid size-10 place-items-center rounded-xl", paymentMethod === "card" ? "bg-primary text-white" : "bg-muted")}><CreditCard size={20} /></div><div className="text-left"><p className="font-bold">Card</p><p className="text-xs text-muted-foreground">Visa, Mastercard (coming soon)</p></div></div>{paymentMethod === "card" && <CheckCircle2 size={20} className="text-primary" />}</button></div>{insufficientFunds && (<div className="mt-3 rounded-xl bg-danger/10 px-4 py-3 text-sm font-bold text-danger">Insufficient wallet balance. You need {formatRand(totalCents - balanceCents)} more.</div>)}</Card>
          </div>
          {/* Order summary */}
          <div><Card><h3 className="font-heading font-black">Order summary</h3><div className="mt-3 max-h-48 space-y-2 overflow-y-auto">{items.map((ci) => (<div key={ci.item.id} className="flex justify-between text-sm"><span className="text-muted-foreground">{ci.quantity}× {ci.item.name}</span><span className="font-bold tabular-nums">{formatRand(ci.item.priceCents * ci.quantity)}</span></div>))}</div><div className="mt-4 space-y-2 border-t border-border pt-4 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Subtotal</span><span className="font-bold tabular-nums">{formatRand(subtotalCents)}</span></div><div className="flex justify-between text-success"><span>Student discount</span><span className="font-bold tabular-nums">−{formatRand(studentDiscountCents)}</span></div>{orderType === "delivery" && (<div className="flex justify-between"><span className="text-muted-foreground">Delivery</span><span className="font-bold tabular-nums">{formatRand(deliveryFeeCents)}</span></div>)}</div><div className="mt-4 flex items-center justify-between border-t border-border pt-4"><span className="font-heading text-lg font-black">Total</span><span className="font-heading text-2xl font-black text-primary tabular-nums">{formatRand(orderType === "delivery" ? totalCents : totalCents - deliveryFeeCents)}</span></div><Button className="mt-4 w-full" disabled={isProcessing || insufficientFunds || (paymentMethod === "card")} onClick={handleCheckout}>{isProcessing ? (<motion.div animate={reduced ? undefined : { rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: "linear" }} className="size-5 rounded-full border-2 border-white/30 border-t-white" />) : (<>Place order <ArrowRight size={18} /></>)}</Button>{paymentMethod === "card" && (<p className="mt-2 text-center text-xs text-muted-foreground">Card payments coming soon</p>)}</Card></div>
        </div>
      </div>
    </AppShell>
  );
}

import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/selection-controls";
import { useSettings } from "@/contexts/settings-context";
import { useAuth } from "@/contexts/auth-context";
import { Bell, Shield, CreditCard, Moon } from "lucide-react";
import { useTheme } from "@/contexts/theme-context";

export function SettingsPage() {
  const { settings, updateNotification, updatePrivacy, updatePayment } = useSettings();
  const { user } = useAuth();
  const { theme, setTheme } = useTheme();

  return (
    <AppShell>
      <div className="mx-auto max-w-2xl space-y-6">
        <div>
          <h1 className="font-heading text-2xl font-black lg:text-3xl">Settings</h1>
          <p className="mt-1 text-sm text-muted-foreground">Customize PayPlate your way</p>
        </div>

        {/* Theme */}
        <Card>
          <div className="flex items-center gap-2">
            <Moon size={18} className="text-primary" />
            <h3 className="font-heading font-black">Appearance</h3>
          </div>
          <div className="mt-4 flex gap-3">
            {(["light", "dark", "dev"] as const).map((t) => (
              <button
                key={t}
                onClick={() => setTheme(t)}
                className={`flex-1 rounded-xl border-2 p-3 text-sm font-bold capitalize transition-all ${
                  theme === t ? "border-primary bg-primary/5 text-primary" : "border-border text-muted-foreground"
                }`}
              >
                {t}
              </button>
            ))}
          </div>
        </Card>

        {/* Notifications */}
        <Card>
          <div className="flex items-center gap-2">
            <Bell size={18} className="text-primary" />
            <h3 className="font-heading font-black">Notifications</h3>
          </div>
          <div className="mt-4 space-y-4">
            <Checkbox
              checked={settings.notifications.orderUpdates}
              onChange={(v) => updateNotification("orderUpdates", v)}
              label="Order status updates"
            />
            <Checkbox
              checked={settings.notifications.rewards}
              onChange={(v) => updateNotification("rewards", v)}
              label="Reward points & tier updates"
            />
            <Checkbox
              checked={settings.notifications.offers}
              onChange={(v) => updateNotification("offers", v)}
              label="Student-exclusive offers"
            />
          </div>
        </Card>

        {/* Privacy */}
        <Card>
          <div className="flex items-center gap-2">
            <Shield size={18} className="text-primary" />
            <h3 className="font-heading font-black">Privacy</h3>
          </div>
          <div className="mt-4 space-y-4">
            <Checkbox
              checked={settings.privacy.showProfile}
              onChange={(v) => updatePrivacy("showProfile", v)}
              label="Show profile to other students"
            />
            <Checkbox
              checked={settings.privacy.shareOrderHistory}
              onChange={(v) => updatePrivacy("shareOrderHistory", v)}
              label="Share order history for recommendations"
            />
          </div>
        </Card>

        {/* Payment */}
        <Card>
          <div className="flex items-center gap-2">
            <CreditCard size={18} className="text-primary" />
            <h3 className="font-heading font-black">Payment</h3>
          </div>
          <div className="mt-4 space-y-4">
            <div>
              <p className="mb-2 text-sm font-bold">Default payment method</p>
              <div className="flex gap-3">
                {(["wallet", "card"] as const).map((m) => (
                  <button
                    key={m}
                    onClick={() => updatePayment("defaultMethod", m)}
                    className={`flex-1 rounded-xl border-2 p-3 text-sm font-bold capitalize transition-all ${
                      settings.payment.defaultMethod === m ? "border-primary bg-primary/5 text-primary" : "border-border text-muted-foreground"
                    }`}
                  >
                    {m}
                  </button>
                ))}
              </div>
            </div>
            <Checkbox
              checked={settings.payment.autoTopUp}
              onChange={(v) => updatePayment("autoTopUp", v)}
              label="Auto top-up when balance is low"
            />
          </div>
        </Card>

        {user && (
          <Card className="bg-muted">
            <p className="text-sm text-muted-foreground">Account: {user.email}</p>
            <p className="mt-1 text-xs text-muted-foreground">Member since {new Date(user.createdAt).toLocaleDateString("en-ZA")}</p>
          </Card>
        )}
      </div>
    </AppShell>
  );
}

import { useState } from "react";
import { useNavigate } from "@/lib/router-compat";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronRight, Wallet, Trophy, Utensils } from "lucide-react";
import { Button } from "@/components/ui/button";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";

const ONBOARD_KEY = "payplate_onboarded";

const slides = [
  {
    icon: <Utensils size={48} />,
    title: "Discover affordable meals",
    description: "Find campus restaurants with student-exclusive discounts, all in one place.",
    gradient: "from-primary/20 via-accent/10 to-transparent",
  },
  {
    icon: <Wallet size={48} />,
    title: "Pay with student wallet",
    description: "Top up your PayPlate wallet and pay securely — no card needed on campus.",
    gradient: "from-blue-500/20 via-primary/10 to-transparent",
  },
  {
    icon: <Trophy size={48} />,
    title: "Earn rewards every meal",
    description: "Every order earns reward points. Climb tiers and unlock free meals.",
    gradient: "from-rewards/20 via-amber-500/10 to-transparent",
  },
];

export function OnboardingPage() {
  const navigate = useNavigate();
  const reduced = usePrefersReducedMotion();
  const [index, setIndex] = useState(0);

  function finish() {
    localStorage.setItem(ONBOARD_KEY, "1");
    navigate("/register");
  }

  function next() {
    if (index < slides.length - 1) setIndex(index + 1);
    else finish();
  }

  const slide = slides[index];

  return (
    <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center overflow-hidden bg-background px-6">
      {/* Skip */}
      <button
        onClick={finish}
        className="absolute right-5 top-5 text-sm font-bold text-muted-foreground transition-colors hover:text-text"
      >
        Skip
      </button>

      {/* Slide content */}
      <AnimatePresence mode="wait">
        <motion.div
          key={index}
          initial={reduced ? undefined : { opacity: 0, x: 60 }}
          animate={{ opacity: 1, x: 0 }}
          exit={reduced ? undefined : { opacity: 0, x: -60 }}
          transition={{ type: "spring", stiffness: 300, damping: 30 }}
          className="flex flex-col items-center text-center"
        >
          {/* Illustration */}
          <div className={`relative mb-10 grid size-56 place-items-center rounded-[2.5rem] bg-gradient-to-br ${slide.gradient}`}>
            <div className="absolute inset-0 rounded-[2.5rem] glass" />
            <motion.div
              animate={reduced ? undefined : { y: [0, -10, 0] }}
              transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
              className="relative grid size-24 place-items-center rounded-full bg-primary text-white shadow-lift"
            >
              {slide.icon}
            </motion.div>
            {/* Floating particles */}
            {!reduced && (
              <>
                <div className="absolute left-6 top-8 size-2 rounded-full bg-primary/40 animate-float" />
                <div className="absolute right-8 top-12 size-1.5 rounded-full bg-accent/50 animate-float-slow" />
                <div className="absolute bottom-10 left-10 size-2 rounded-full bg-rewards/40 animate-float" />
              </>
            )}
          </div>

          <h2 className="font-heading text-2xl font-black tracking-tight">{slide.title}</h2>
          <p className="mt-3 max-w-xs text-base leading-relaxed text-muted-foreground">
            {slide.description}
          </p>
        </motion.div>
      </AnimatePresence>

      {/* Progress dots */}
      <div className="mt-10 flex items-center gap-2">
        {slides.map((_, i) => (
          <button
            key={i}
            onClick={() => setIndex(i)}
            aria-label={`Go to slide ${i + 1}`}
            className={`h-2 rounded-full transition-all duration-300 ${
              i === index ? "w-8 bg-primary" : "w-2 bg-muted-foreground/30"
            }`}
          />
        ))}
      </div>

      {/* CTA */}
      <div className="mt-8 w-full max-w-xs">
        <Button className="w-full" onClick={next}>
          {index === slides.length - 1 ? "Get started" : "Next"}
          <ChevronRight size={18} />
        </Button>
      </div>
    </div>
  );
}

export function hasOnboarded(): boolean {
  return localStorage.getItem(ONBOARD_KEY) === "1";
}

import { useEffect, useState } from "react";
import { useSearchParams } from "@/lib/router-compat";
import { motion } from "framer-motion";
import { Search, SlidersHorizontal, X } from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { EmptyState } from "@/components/ui/empty-state";
import { RestaurantCard } from "@/components/domain/restaurant-card";
import { useRestaurants } from "@/contexts/restaurants-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import type { Restaurant } from "@/types/payplate";

const CATEGORIES = ["All", "Burgers", "Pizza", "Bowls", "Coffee", "Sushi", "Ramen"];

export function RestaurantsPage() {
  const [searchParams] = useSearchParams();
  const initialQuery = searchParams.get("q") ?? "";
  const { restaurants, isLoading, error, search, retry } = useRestaurants();
  const reduced = usePrefersReducedMotion();

  const [query, setQuery] = useState(initialQuery);
  const [activeCategory, setActiveCategory] = useState("All");
  const [filtered, setFiltered] = useState<Restaurant[]>([]);
  const [showFilters, setShowFilters] = useState(false);

  useEffect(() => {
    setFiltered(restaurants);
  }, [restaurants]);

  useEffect(() => {
    if (initialQuery) doSearch(initialQuery);
  }, [initialQuery]);

  async function doSearch(q: string) {
    const results = await search(q);
    setFiltered(results);
  }

  function handleCategory(cat: string) {
    setActiveCategory(cat);
    if (cat === "All") {
      setFiltered(restaurants);
    } else {
      setFiltered(restaurants.filter((r) => r.categories.some((c) => c.toLowerCase().includes(cat.toLowerCase()))));
    }
  }

  function clearFilters() {
    setQuery("");
    setActiveCategory("All");
    setFiltered(restaurants);
  }

  return (
    <AppShell>
      <div className="space-y-6">
        <div>
          <h1 className="font-heading text-2xl font-black lg:text-3xl">Restaurants</h1>
          <p className="mt-1 text-sm text-muted-foreground">{filtered.length} places to explore</p>
        </div>

        {/* Search + filter toggle */}
        <div className="flex gap-3">
          <div className="flex-1">
            <Input
              icon={<Search size={18} />}
              placeholder="Search restaurants…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") doSearch(query);
              }}
            />
          </div>
          <Button
            variant="secondary"
            onClick={() => setShowFilters((v) => !v)}
            className="px-4"
            aria-label="Toggle filters"
          >
            <SlidersHorizontal size={18} />
          </Button>
        </div>

        {/* Category pills */}
        <motion.div
          initial={reduced ? undefined : { opacity: 0 }}
          animate={{ opacity: 1 }}
          className="flex flex-wrap gap-2"
        >
          {CATEGORIES.map((cat) => (
            <button
              key={cat}
              onClick={() => handleCategory(cat)}
              className={`rounded-full px-4 py-2 text-sm font-bold transition-all duration-200 ${
                activeCategory === cat
                  ? "bg-primary text-white shadow-lift"
                  : "bg-card text-muted-foreground ring-1 ring-border hover:text-text"
              }`}
            >
              {cat}
            </button>
          ))}
          {(activeCategory !== "All" || query) && (
            <button
              onClick={clearFilters}
              className="inline-flex items-center gap-1 rounded-full px-3 py-2 text-sm font-bold text-danger hover:underline"
            >
              <X size={14} /> Clear
            </button>
          )}
        </motion.div>

        {/* Results */}
        {isLoading ? (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3, 4, 5, 6].map((i) => <Skeleton key={i} className="h-64" />)}
          </div>
        ) : error ? (
          <EmptyState
            icon={<Search size={32} />}
            title="Something went wrong"
            description={error}
            action={<Button onClick={retry}>Try again</Button>}
          />
        ) : filtered.length === 0 ? (
          <EmptyState
            icon={<Search size={32} />}
            title="No restaurants found"
            description="Try a different search or category."
            action={<Button onClick={clearFilters}>Clear filters</Button>}
          />
        ) : (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filtered.map((r, i) => (
              <motion.div
                key={r.id}
                initial={reduced ? undefined : { opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
              >
                <RestaurantCard restaurant={r} />
              </motion.div>
            ))}
          </div>
        )}
      </div>
    </AppShell>
  );
}

import { useState } from "react";
import { useNavigate } from "@/lib/router-compat";
import { motion } from "framer-motion";
import { GraduationCap, CircleCheck as CheckCircle2, Clock, Circle as XCircle, Upload, ArrowLeft, ShieldCheck } from "lucide-react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/contexts/auth-context";
import { useToast } from "@/contexts/toast-context";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { cn } from "@/lib/utils";

const timelineSteps = [
  { label: "Account created", desc: "Your PayPlate account is ready.", status: "complete" },
  { label: "Submit verification", desc: "Enter your student details.", status: "current" },
  { label: "Under review", desc: "We verify your student status.", status: "pending" },
  { label: "Verified", desc: "Unlock student discounts.", status: "pending" },
];

export function VerificationPage() {
  const { user, verifyStudent } = useAuth();
  const { showToast } = useToast();
  const navigate = useNavigate();
  const reduced = usePrefersReducedMotion();

  const [university, setUniversity] = useState(user?.university ?? "");
  const [studentNumber, setStudentNumber] = useState(user?.studentNumber ?? "");
  const [faculty, setFaculty] = useState("");
  const [campus, setCampus] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const verificationStatus = user?.verificationStatus ?? "unverified";

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!university.trim() || !studentNumber.trim() || !faculty.trim() || !campus.trim()) {
      showToast("Please fill in all fields", "error");
      return;
    }
    setIsSubmitting(true);
    await verifyStudent(university, studentNumber, faculty, campus);
    setIsSubmitting(false);
    showToast("Verification submitted! We'll review it shortly.", "success");
  }

  const statusConfig = {
    unverified: { label: "Not verified", color: "bg-muted text-muted-foreground", icon: GraduationCap },
    pending: { label: "Under review", color: "bg-warning/10 text-warning", icon: Clock },
    verified: { label: "Verified student", color: "bg-success/10 text-success", icon: CheckCircle2 },
    rejected: { label: "Rejected", color: "bg-danger/10 text-danger", icon: XCircle },
  };

  const currentStatus = statusConfig[verificationStatus];

  return (
    <AppShell>
      <div className="mx-auto max-w-2xl space-y-6">
        <div className="flex items-center gap-3">
          <button onClick={() => navigate("/profile")} className="grid size-10 place-items-center rounded-xl bg-card ring-1 ring-border">
            <ArrowLeft size={18} />
          </button>
          <div>
            <h1 className="font-heading text-2xl font-black">Student verification</h1>
            <p className="text-sm text-muted-foreground">Unlock exclusive campus discounts</p>
          </div>
        </div>

        {/* Status card */}
        <motion.div
          initial={reduced ? undefined : { opacity: 0, y: 15 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <Card className={cn("flex items-center gap-4", currentStatus.color)}>
            <div className={cn("grid size-14 place-items-center rounded-2xl", currentStatus.color)}>
              <currentStatus.icon size={26} />
            </div>
            <div className="flex-1">
              <h3 className="font-heading font-black">Status: {currentStatus.label}</h3>
              <p className="text-sm text-muted-foreground">
                {verificationStatus === "verified"
                  ? "You have access to all student-exclusive discounts."
                  : verificationStatus === "pending"
                  ? "Your verification is being reviewed. This usually takes 1–2 business days."
                  : "Submit your details below to start the verification process."}
              </p>
            </div>
            <Badge className={cn("shrink-0", currentStatus.color)}>{currentStatus.label}</Badge>
          </Card>
        </motion.div>

        {/* Timeline */}
        <Card>
          <h3 className="font-heading font-black">Verification timeline</h3>
          <div className="mt-4 space-y-1">
            {timelineSteps.map((step, i) => {
              const isLast = i === timelineSteps.length - 1;
              const iconMap = {
                complete: <CheckCircle2 size={16} className="text-success" />,
                current: <Clock size={16} className="text-warning" />,
                pending: <div className="size-3 rounded-full border-2 border-muted-foreground/30" />,
              };
              return (
                <div key={i} className="flex gap-3">
                  <div className="flex flex-col items-center">
                    <div className="grid size-8 place-items-center rounded-full bg-card ring-1 ring-border">
                      {iconMap[step.status as keyof typeof iconMap]}
                    </div>
                    {!isLast && <div className="h-8 w-px bg-border" />}
                  </div>
                  <div className="pb-4">
                    <p className="font-bold text-sm">{step.label}</p>
                    <p className="text-xs text-muted-foreground">{step.desc}</p>
                  </div>
                </div>
              );
            })}
          </div>
        </Card>

        {/* Verification form — only show if unverified */}
        {verificationStatus === "unverified" && (
          <Card>
            <div className="mb-4 flex items-center gap-2">
              <ShieldCheck size={18} className="text-primary" />
              <h3 className="font-heading font-black">Your details</h3>
            </div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <Input
                label="University"
                placeholder="e.g. University of Cape Town"
                value={university}
                onChange={(e) => setUniversity(e.target.value)}
              />
              <Input
                label="Student number"
                placeholder="e.g. STU2026001"
                value={studentNumber}
                onChange={(e) => setStudentNumber(e.target.value)}
              />
              <Input
                label="Faculty"
                placeholder="e.g. Engineering"
                value={faculty}
                onChange={(e) => setFaculty(e.target.value)}
              />
              <Input
                label="Campus"
                placeholder="e.g. Main Campus"
                value={campus}
                onChange={(e) => setCampus(e.target.value)}
              />

              {/* Upload placeholder */}
              <div>
                <label className="mb-1.5 block text-sm font-bold">Student card upload</label>
                <div className="rounded-2xl border-2 border-dashed border-border p-6 text-center transition-colors hover:border-primary">
                  <Upload size={28} className="mx-auto text-muted-foreground" />
                  <p className="mt-2 text-sm font-bold">Upload your student card</p>
                  <p className="mt-1 text-xs text-muted-foreground">JPG, PNG, or PDF — max 5MB</p>
                </div>
              </div>

              <Button type="submit" disabled={isSubmitting} className="w-full">
                {isSubmitting ? "Submitting…" : "Submit for verification"}
              </Button>
            </form>
          </Card>
        )}

        {verificationStatus === "pending" && (
          <Card className="bg-warning/5">
            <div className="flex items-center gap-3">
              <Clock size={24} className="text-warning" />
              <div>
                <h3 className="font-heading font-black">Verification in progress</h3>
                <p className="text-sm text-muted-foreground">We'll notify you once your status is confirmed. This usually takes 1–2 business days.</p>
              </div>
            </div>
          </Card>
        )}

        {verificationStatus === "verified" && (
          <Card className="bg-success/5">
            <div className="flex items-center gap-3">
              <CheckCircle2 size={24} className="text-success" />
              <div>
                <h3 className="font-heading font-black">You're verified!</h3>
                <p className="text-sm text-muted-foreground">You now have access to student-exclusive discounts at every restaurant.</p>
              </div>
            </div>
            <Button className="mt-4 w-full" onClick={() => navigate("/restaurants")}>
              Browse restaurants with discounts
            </Button>
          </Card>
        )}
      </div>
    </AppShell>
  );
}
